er;background:rgba(255,255,255,.08);color:var(--gold2);font-size:13px}.admin-sidebar form{margin-top:26px;padding-top:22px;border-top:1px solid rgba(255,255,255,.1)}.admin-main{padding:34px clamp(22px,4vw,56px)}.admin-top{display:flex;align-items:flex-start;justify-content:space-between;gap:22px;margin-bottom:26px}.admin-top h2{font-size:31px;line-height:1.1;margin:0;letter-spacing:-.03em}.admin-top p{margin:9px 0 0;color:var(--muted)}.admin-card{position:relative;background:rgba(255,255,255,.86);border:1px solid rgba(228,232,238,.9);border-radius:24px;padding:24px;margin-bottom:24px;box-shadow:0 18px 55px rgba(16,36,58,.08);backdrop-filter:blur(12px)}.admin-card h3{margin:0 0 6px;font-size:18px;letter-spacing:-.01em}.admin-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.admin-grid .full{grid-column:1/-1}label{display:block;font-size:11px;font-weight:800;color:#677386;text-transform:uppercase;letter-spacing:.08em}input,select,textarea{width:100%;border:1px solid var(--line);border-radius:15px;background:#fff;color:var(--ink);padding:13px 14px;margin-top:8px;font:inherit;outline:none;transition:border .2s,box-shadow .2s,transform .2s}input:focus,select:focus,textarea:focus{border-color:rgba(196,154,56,.72);box-shadow:0 0 0 4px rgba(196,154,56,.12)}textarea{min-height:110px;resize:vertical}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:0;border-radius:999px;background:linear-gradient(135deg,var(--navy2),var(--navy));color:#fff;padding:12px 19px;text-decoration:none;font-weight:800;letter-spacing:.02em;cursor:pointer;box-shadow:0 10px 24px rgba(16,36,58,.16);transition:.22s ease}.btn:hover{transform:translateY(-1px);box-shadow:0 14px 32px rgba(16,36,58,.22)}.btn.gold{background:linear-gradient(135deg,var(--gold2),var(--gold));color:#231b0a}.btn.danger{background:linear-gradient(135deg,#d85c5c,var(--danger))}.btn.ghost{background:#fff;color:var(--navy);border:1px solid var(--line);box-shadow:none}.btn.small{pa