        .upload-field small{display:block;margin:8px 2px 0;color:var(--muted);font-size:11px;font-weight:500;line-height:1.55;letter-spacing:0;text-transform:none}.upload-field input[type=file]{min-height:50px;padding:10px;color:#445165}.upload-field input[type=file]::file-selector-button{border:0;border-radius:999px;background:var(--navy2);color:#fff;padding:9px 14px;margin-right:12px;font-weight:700;cursor:pointer}.upload-preview{display:grid;grid-template-columns:84px 1fr;align-items:center;gap:12px;margin-top:12px;padding:9px;border:1px solid var(--line);border-radius:14px;background:#fff}.upload-preview img{width:84px;height:62px;border-radius:9px;object-fit:cover}.upload-preview b{font-size:11px;color:#687587;text-transform:none;letter-spacing:0}.popup-upload{padding:18px;border:1px dashed #cbd4df;border-radius:18px;background:#f9fbfd}.media-library{margin:0;padding:18px;border:1px solid var(--line);border-radius:18px;background:#f9fbfd}.media-library legend{padding:0 8px;color:#677386;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.media-library>p{margin:0 0 14px;color:var(--muted);font-size:12px}.media-library-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.media-library-item{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:14px;background:#fff}.media-library-item img,.media-library-item video{display:block;width:100%;height:135px;object-fit:cover;background:#10243a}.media-type{display:block;padding:9px 10px 2px;color:var(--muted);font-size:10px}.media-remove{display:flex;align-items:center;gap:7px;padding:7px 10px 11px;color:var(--danger);font-size:11px}.media-remove input{width:17px;height:17px;margin:0;accent-color:var(--danger)}@media(max-width:900px){.media-library-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.media-library-grid{grid-template-columns:1fr}}
